/// One sRGB color, 0...1 per channel, read from a `#RRGGBB` / `#RRGGBBAA` token.
public struct TMLRGBA: Sendable, Hashable {
    public let red: Double
    public let green: Double
    public let blue: Double
    public let alpha: Double
    /// The raw value, 0xRRGGBBAA.
    public let rgba: UInt32

    /// `rgba` is 0xRRGGBBAA.
    public init(rgba: UInt32) {
        self.rgba = rgba
        red = Double((rgba >> 24) & 0xFF) / 255
        green = Double((rgba >> 16) & 0xFF) / 255
        blue = Double((rgba >> 8) & 0xFF) / 255
        alpha = Double(rgba & 0xFF) / 255
    }
}

extension Color {
    /// A color that follows the system appearance: `light` in light mode, `dark` in dark mode.
    public init(tmlLight light: TMLRGBA, dark: TMLRGBA) {
        #if canImport(UIKit)
        self.init(uiColor: UIColor { traits in
            let c = traits.userInterfaceStyle == .dark ? dark : light
            return UIColor(red: c.red, green: c.green, blue: c.blue, alpha: c.alpha)
        })
        #elseif canImport(AppKit)
        self.init(nsColor: NSColor(name: nil) { appearance in
            let isDark = appearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
            let c = isDark ? dark : light
            return NSColor(srgbRed: c.red, green: c.green, blue: c.blue, alpha: c.alpha)
        })
        #else
        self.init(.sRGB, red: light.red, green: light.green, blue: light.blue, opacity: light.alpha)
        #endif
    }

    /// A fixed color (no appearance switch), for one side of a token.
    public init(tml c: TMLRGBA) {
        self.init(.sRGB, red: c.red, green: c.green, blue: c.blue, opacity: c.alpha)
    }
}

