/// Spacing in points. There is no space-7: the scale goes from space-6 (24) straight to space-8 (32).
public enum TMLSpacing {
    /// Gap between an icon and its label inside a pill; half-step of the 8pt grid.
    public static let space1: CGFloat = 4
    /// Inset of floating sheets and bars from the screen edge; gap between stacked buttons.
    public static let space2: CGFloat = 8
    /// Gap between an avatar and its text in a row; padding inside small cards.
    public static let space3: CGFloat = 12
    /// Screen margins on standard phones; list row side padding.
    public static let space4: CGFloat = 16
    /// Screen margins on larger phones; padding inside map sheets.
    public static let space5: CGFloat = 20
    /// Gap between sections on a screen.
    public static let space6: CGFloat = 24
    /// Gap above a screen's primary action when the screen has room.
    public static let space8: CGFloat = 32
    /// Minimum height and width of anything tappable: 44pt on iOS.
    public static let tapTarget: CGFloat = 44
    /// Minimum height and width of anything tappable on Android (48dp) and on the viewer's browser page (48px).
    public static let tapTargetLg: CGFloat = 48
}

/// Corner radii in points (iOS). Android uses `radius.android` in tokens.json instead.
public enum TMLRadius {
    /// Small thumbnails and keycap-sized elements.
    public static let xs: CGFloat = 8
    /// Tiles and neutral buttons inside a map sheet (radius-sheet minus 20pt padding, so corners stay concentric).
    public static let md: CGFloat = 18
    /// Grouped lists, cards and map previews.
    public static let lg: CGFloat = 26
    /// Floating sheets and the picture-in-picture mini map, following the device's corners.
    public static let sheet: CGFloat = 38
    /// Buttons, status pills, name capsules and the distance capsule.
    public static let pill: CGFloat = 999
}

// MARK: - Shadow

/// One CSS-style shadow per appearance. SwiftUI's `.shadow(radius:)` is about half the CSS blur.
public struct TMLShadowStyle: Sendable, Hashable {
    public let x: CGFloat
    public let y: CGFloat
    /// CSS blur radius.
    public let blur: CGFloat
    public let color: TMLRGBA
    /// For SwiftUI's `.shadow(color:radius:x:y:)`.
    public var swiftUIRadius: CGFloat { blur / 2 }
}

/// Shadows go on three things only: markers (shadow-marker), the floating mini map (shadow-float) and Android's system stand-ins (a soft shadow of their own). Never on glass, which separates with glass-edge.
public enum TMLShadow: String, CaseIterable, Sendable {
    /// Person markers on the map.
    case marker = "shadow-marker"
    /// The Android picture-in-picture mini map floating over the call screen.
    case float = "shadow-float"

    public var light: TMLShadowStyle {
        switch self {
        case .marker: TMLShadowStyle(x: 0, y: 6, blur: 16, color: TMLRGBA(rgba: 0x11181B40))
        case .float: TMLShadowStyle(x: 0, y: 18, blur: 48, color: TMLRGBA(rgba: 0x11181B2E))
        }
    }

    public var dark: TMLShadowStyle {
        switch self {
        case .marker: TMLShadowStyle(x: 0, y: 8, blur: 20, color: TMLRGBA(rgba: 0x0000008C))
        case .float: TMLShadowStyle(x: 0, y: 24, blur: 60, color: TMLRGBA(rgba: 0x00000099))
        }
    }

    /// The shadow color, switching with light and dark mode.
    public var color: Color { Color(tmlLight: light.color, dark: dark.color) }
}

extension View {
    /// Applies a token shadow for the current appearance.
    public func tmlShadow(_ token: TMLShadow, colorScheme: ColorScheme) -> some View {
        let s = colorScheme == .dark ? token.dark : token.light
        return shadow(color: Color(tml: s.color), radius: s.swiftUIRadius, x: s.x, y: s.y)
    }
}

// MARK: - Type

/// Font family names. Gabarito (display) is bundled in the app (SIL OFL). Text is SF Pro, the system font,
/// on Apple platforms (design-system/README.md, FSD §11); Figtree is the text face everywhere else.
public enum TMLFontFamily {
    /// Display: titles, numbers and badges. CSS stack: "Gabarito", -apple-system, BlinkMacSystemFont, system-ui, sans-serif
    public static let display = "Gabarito"
    /// Text off Apple platforms (Android, the web outside Safari). iOS uses the system font. CSS stack: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Figtree", system-ui, sans-serif
    public static let textNonApple = "Figtree"
}

/// The Dynamic Type style a token scales with.
public enum TMLRelativeTextStyle: String, Sendable {
    case largeTitle, title, title2, title3, headline, body, callout, subheadline, footnote, caption, caption2

    public var textStyle: Font.TextStyle {
        switch self {
        case .largeTitle: .largeTitle
        case .title: .title
        case .title2: .title2
        case .title3: .title3
        case .headline: .headline
        case .body: .body
        case .callout: .callout
        case .subheadline: .subheadline
        case .footnote: .footnote
        case .caption: .caption
        case .caption2: .caption2
        }
    }
}

/// One type style from tokens.json, sized at the default (Large) Dynamic Type size.
public struct TMLTypeStyle: Sendable, Hashable {
    public enum Family: String, Sendable { case display, text }

    public let name: String
    public let family: Family
    /// Point size at the default text size.
    public let size: CGFloat
    /// Line height in points at the default text size.
    public let lineHeight: CGFloat
    /// CSS weight: 400 regular, 500 medium, 600 semibold, 700 bold, 800 heavy.
    public let cssWeight: Int
    /// Letter spacing in points at the default text size (`.tracking`).
    public let tracking: CGFloat
    public let relativeTo: TMLRelativeTextStyle

    public var weight: Font.Weight {
        switch cssWeight {
        case ..<350: .light
        case ..<450: .regular
        case ..<550: .medium
        case ..<650: .semibold
        case ..<750: .bold
        case ..<850: .heavy
        default: .black
        }
    }

    /// Display styles: Gabarito, scaled with Dynamic Type relative to `relativeTo`.
    /// Text styles: SF Pro through the matching system text style, so they scale like native text.
    public var font: Font {
        switch family {
        case .display: .custom(TMLFontFamily.display, size: size, relativeTo: relativeTo.textStyle).weight(weight)
        case .text: .system(relativeTo.textStyle, design: .default, weight: weight)
        }
    }
}

/// The type scale. Apply with `.tmlTextStyle(TMLType.title2)`, which adds tracking and line height.
public enum TMLType {
    /// The one big title at the top of Home and the share screen. Gabarito Bold, bundled in the app and scaled with Dynamic Type. (Titles; 34/41pt, weight 700. Sample: "Share where you are")
    public static let largeTitle = TMLTypeStyle(name: "large-title", family: .display, size: 34, lineHeight: 41, cssWeight: 700, tracking: -0.6, relativeTo: .largeTitle)
    /// Screen titles on pushed screens. Gabarito Bold, scaled with Dynamic Type. (Titles; 28/34pt, weight 700. Sample: "Your mascot")
    public static let title1 = TMLTypeStyle(name: "title-1", family: .display, size: 28, lineHeight: 34, cssWeight: 700, tracking: -0.45, relativeTo: .title)
    /// Sheet titles over the map. Gabarito Bold, scaled with Dynamic Type. (Titles; 22/28pt, weight 700. Sample: "You're both live")
    public static let title2 = TMLTypeStyle(name: "title-2", family: .display, size: 22, lineHeight: 28, cssWeight: 700, tracking: -0.3, relativeTo: .title2)
    /// Section heads and the viewer page's heading. iOS: .title3. (Text; 20/25pt, weight 600. Sample: "Alex is sharing their location with you")
    public static let title3 = TMLTypeStyle(name: "title-3", family: .text, size: 20, lineHeight: 25, cssWeight: 600, tracking: -0.45, relativeTo: .title3)
    /// Button labels and list row titles. iOS: .headline. (Text; 17/22pt, weight 600. Sample: "Share live location")
    public static let headline = TMLTypeStyle(name: "headline", family: .text, size: 17, lineHeight: 22, cssWeight: 600, tracking: -0.43, relativeTo: .headline)
    /// Default reading text. iOS: .body. (Text; 17/22pt, weight 400. Sample: "The person you're talking to follows you live in their browser.")
    public static let body = TMLTypeStyle(name: "body", family: .text, size: 17, lineHeight: 22, cssWeight: 400, tracking: -0.43, relativeTo: .body)
    /// Sheet subtitles and explanations under a title. iOS: .callout. (Text; 16/21pt, weight 400. Sample: "Visible until your call ends.")
    public static let callout = TMLTypeStyle(name: "callout", family: .text, size: 16, lineHeight: 21, cssWeight: 400, tracking: -0.31, relativeTo: .callout)
    /// List row details and status text. iOS: .subheadline. (Text; 15/20pt, weight 400. Sample: "Sharing back · updated 3 s ago")
    public static let subheadline = TMLTypeStyle(name: "subheadline", family: .text, size: 15, lineHeight: 20, cssWeight: 400, tracking: -0.23, relativeTo: .subheadline)
    /// Small print under buttons and inside pills. iOS: .footnote. (Text; 13/18pt, weight 400. Sample: "Your browser will ask for permission first.")
    public static let footnote = TMLTypeStyle(name: "footnote", family: .text, size: 13, lineHeight: 18, cssWeight: 400, tracking: -0.08, relativeTo: .footnote)
    /// Name capsules under map markers. iOS: .caption with medium weight. (Text; 12/16pt, weight 500. Sample: "Alex")
    public static let caption1 = TMLTypeStyle(name: "caption-1", family: .text, size: 12, lineHeight: 16, cssWeight: 500, tracking: 0, relativeTo: .caption)
    /// The smallest allowed text: map labels only, never below 11pt, growing with the text size. Sentence case or the place's own name, never uppercase. iOS: .caption2. (Text; 11/13pt, weight 400. Sample: "Alder Park")
    public static let caption2 = TMLTypeStyle(name: "caption-2", family: .text, size: 11, lineHeight: 13, cssWeight: 400, tracking: 0.06, relativeTo: .caption2)
    /// The big distance on the Live Activity and stat tiles. Gabarito Bold; tabular figures on iOS come from SF Pro with .monospacedDigit(). (Numbers; 28/34pt, weight 700. Sample: "1.2 km")
    public static let distance = TMLTypeStyle(name: "distance", family: .display, size: 28, lineHeight: 34, cssWeight: 700, tracking: -0.4, relativeTo: .title)
    /// Numbers inline: the distance capsule on the map, call timers. (Numbers; 15/20pt, weight 700. Sample: "1.2 km · 04:12")
    public static let metric = TMLTypeStyle(name: "metric", family: .display, size: 15, lineHeight: 20, cssWeight: 700, tracking: -0.1, relativeTo: .subheadline)
    /// Uppercase status badges (LIVE, LIVE TOGETHER, NO SIGNAL, NO CONNECTION). The only uppercase text anywhere. (Numbers; 11/13pt, weight 800. Sample: "LIVE")
    public static let badge = TMLTypeStyle(name: "badge", family: .display, size: 11, lineHeight: 13, cssWeight: 800, tracking: 0.6, relativeTo: .caption2)

    public static let all: [TMLTypeStyle] = [
        largeTitle,
        title1,
        title2,
        title3,
        headline,
        body,
        callout,
        subheadline,
        footnote,
        caption1,
        caption2,
        distance,
        metric,
        badge,
    ]
}

/// Font, tracking and line height for a token style, all scaled with Dynamic Type.
public struct TMLTextStyleModifier: ViewModifier {
    public let style: TMLTypeStyle
    @ScaledMetric private var tracking: CGFloat
    @ScaledMetric private var lineSpacing: CGFloat

    public init(_ style: TMLTypeStyle) {
        self.style = style
        _tracking = ScaledMetric(wrappedValue: style.tracking, relativeTo: style.relativeTo.textStyle)
        _lineSpacing = ScaledMetric(wrappedValue: TMLTextStyleModifier.extraLeading(style), relativeTo: style.relativeTo.textStyle)
    }

    /// Text styles already carry the system's leading (the tokens match iOS's defaults), so only
    /// Gabarito styles get extra line spacing: the token line height minus the font's own.
    static func extraLeading(_ style: TMLTypeStyle) -> CGFloat {
        guard style.family == .display else { return 0 }
        #if canImport(UIKit)
        let natural = UIFont(name: TMLFontFamily.display, size: style.size)?.lineHeight ?? style.size * 1.2
        #elseif canImport(AppKit)
        let natural: CGFloat = NSFont(name: TMLFontFamily.display, size: style.size).map { $0.ascender - $0.descender + $0.leading } ?? style.size * 1.2
        #else
        let natural = style.size * 1.2
        #endif
        return max(0, style.lineHeight - natural)
    }

    public func body(content: Content) -> some View {
        content.font(style.font).tracking(tracking).lineSpacing(lineSpacing)
    }
}

extension View {
    /// Applies a Track Me Live type style (font, tracking, line height), scaled with Dynamic Type.
    public func tmlTextStyle(_ style: TMLTypeStyle) -> some View {
        modifier(TMLTextStyleModifier(style))
    }
}
